"""One-shot enrollment tokens (PWA QR) generated by the companion.

Only the SHA-256 of a token is stored (it is the row name): a database leak
does not reveal usable tokens. A token is consumed atomically with a row lock
(SELECT … FOR UPDATE), so two concurrent verifications from different workers
cannot both succeed.
"""

import hashlib
import re
import secrets
from datetime import timedelta

import frappe
from frappe.utils import get_datetime, now_datetime

from speakdo_erpnext.constants import ENROLLMENT_TOKEN_DOCTYPE, ENROLLMENT_TOKEN_TTL_SECONDS, PWA_CHANNEL

TOKEN_PATTERN = re.compile(r"^[A-Za-z0-9._~-]{24,512}$")

ISSUED = "issued"
CONSUMED = "consumed"
REVOKED = "revoked"

# Rejection reasons (sent back in the verify answer).
TOKEN_INVALID = "enrollment_token_invalid"
TOKEN_EXPIRED = "enrollment_token_expired"
TOKEN_CONSUMED = "enrollment_token_consumed"


class TokenRejected(Exception):
	def __init__(self, reason):
		super().__init__(reason)
		self.reason = reason


def token_hash(token):
	return hashlib.sha256(token.encode("utf-8")).hexdigest()


def issue(erp_user_id, channel=PWA_CHANNEL, ttl_seconds=ENROLLMENT_TOKEN_TTL_SECONDS):
	"""Create a token for ``erp_user_id``. Returns (token, expires_at). Never logged."""
	token = secrets.token_urlsafe(32)  # 43 chars of [A-Za-z0-9_-]
	expires_at = now_datetime() + timedelta(seconds=ttl_seconds)
	doc = frappe.new_doc(ENROLLMENT_TOKEN_DOCTYPE)
	doc.name = token_hash(token)
	doc.erp_user = erp_user_id
	doc.channel = channel
	doc.status = ISSUED
	doc.expires_at = expires_at
	doc.db_insert()
	return token, expires_at


def _load_for_update(token):
	if not isinstance(token, str) or not TOKEN_PATTERN.match(token):
		raise TokenRejected(TOKEN_INVALID)
	rows = frappe.db.sql(
		f"select name, erp_user, channel, status, expires_at from `tab{ENROLLMENT_TOKEN_DOCTYPE}` "
		"where name = %s for update",
		(token_hash(token),),
		as_dict=True,
	)
	if not rows:
		raise TokenRejected(TOKEN_INVALID)
	row = rows[0]
	if row.status == CONSUMED:
		raise TokenRejected(TOKEN_CONSUMED)
	if row.status != ISSUED:
		raise TokenRejected(TOKEN_INVALID)
	if get_datetime(row.expires_at) <= now_datetime():
		raise TokenRejected(TOKEN_EXPIRED)
	return row


def peek(token):
	"""Validate without consuming (``consume: false``)."""
	return _load_for_update(token)


def consume(token, terminal_id=None):
	"""Validate and consume in the current transaction. Raises TokenRejected."""
	row = _load_for_update(token)
	frappe.db.set_value(
		ENROLLMENT_TOKEN_DOCTYPE,
		row.name,
		{"status": CONSUMED, "consumed_at": now_datetime(), "terminal_id": terminal_id},
		update_modified=True,
	)
	return row


def revoke_all():
	frappe.db.set_value(ENROLLMENT_TOKEN_DOCTYPE, {"status": ISSUED}, "status", REVOKED)


def purge_expired():
	frappe.db.delete(ENROLLMENT_TOKEN_DOCTYPE, {"expires_at": ("<", now_datetime() - timedelta(days=1))})
